def flatten(obj, sep='.'):
    def _flatten(value, prefix, out):
        if isinstance(value, dict):
            for key, val in value.items():
                new_key = f"{prefix}{sep}{key}" if prefix else str(key)
                _flatten(val, new_key, out)
        elif isinstance(value, list):
            for i, item in enumerate(value):
                new_key = f"{prefix}{sep}{i}" if prefix else str(i)
                _flatten(item, new_key, out)
        else:
            out[prefix] = value

    if not isinstance(obj, dict):
        raise TypeError("flatten() expects a dict as the top-level object")

    result = {}
    _flatten(obj, '', result)
    return result

def flatten(obj, sep='.') -> dict:
    result = {}

    def _flatten(value, prefix):
        if isinstance(value, dict):
            if not value:
                result[prefix] = value
            else:
                for key, val in value.items():
                    new_key = f"{prefix}{sep}{key}" if prefix else str(key)
                    _flatten(val, new_key)
        elif isinstance(value, list):
            if not value:
                result[prefix] = value
            else:
                for i, item in enumerate(value):
                    new_key = f"{prefix}{sep}{i}" if prefix else str(i)
                    _flatten(item, new_key)
        else:
            result[prefix] = value

    if isinstance(obj, dict):
        for key, val in obj.items():
            _flatten(val, str(key))
    else:
        _flatten(obj, "")

    return result

def compare_versions(v1: str, v2: str) -> int:
    def parse(version):
        return [int(part) for part in version.split('.') if part != '']

    a, b = parse(v1), parse(v2)
    length = max(len(a), len(b))
    a += [0] * (length - len(a))
    b += [0] * (length - len(b))

    for x, y in zip(a, b):
        if x < y:
            return -1
        if x > y:
            return 1
    return 0

def compare_versions(v1: str, v2: str) -> int:
    def parts(v):
        return [int(x) for x in v.split(".") if x != ""]

    p1, p2 = parts(v1), parts(v2)
    n = max(len(p1), len(p2))
    for i in range(n):
        a = p1[i] if i < len(p1) else 0
        b = p2[i] if i < len(p2) else 0
        if a < b:
            return -1
        if a > b:
            return 1
    return 0

from functools import wraps


def retry(times: int, exceptions=(Exception,)):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
            raise last_exception
        return wrapper
    return decorator

