from typing import Callable, Tuple, Type


def retry(times: int, exceptions: Tuple[Type[BaseException], ...] = (Exception,)) -> Callable:
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exception = exc
            raise last_exception
        return wrapper
    return decorator

import re


def parse_select(sql: str) -> dict:
    text = sql.strip()

    select_re = re.compile(r'^\s*SELECT\s+(.*?)\s+FROM\s+(.+?)\s*$', re.IGNORECASE | re.DOTALL)
    match = select_re.match(text)
    if not match:
        raise ValueError(f"Invalid SELECT statement: {sql!r}")

    columns_str = match.group(1)
    rest = match.group(2).strip()

    if columns_str.strip() == '*':
        columns = ['*']
    else:
        columns = [c.strip() for c in columns_str.split(',')]

    where_re = re.compile(r'^\s*WHERE\s+(.+?)\s*$', re.IGNORECASE | re.DOTALL)
    where_match = where_re.match(rest)
    if where_match:
        table = rest[:where_match.start()].strip()
        where = where_match.group(1).strip()
    else:
        table = rest.strip()
        where = None

    return {'columns': columns, 'table': table, 'where': where}

import re


def parse_select(sql: str) -> dict:
    text = sql.strip()
    match = re.match(
        r'^\s*select\s+(.*?)\s+from\s+(.+?)(?:\s+where\s+(.+))?$',
        text,
        re.IGNORECASE | re.DOTALL,
    )
    if not match:
        raise ValueError(f"Invalid SELECT statement: {sql!r}")

    columns_part, table_part, where_part = match.groups()

    if columns_part.strip() == '*':
        columns = ['*']
    else:
        columns = [c.strip() for c in columns_part.split(',')]

    table = table_part.strip()
    where = where_part.strip() if where_part else None

    return {'columns': columns, 'table': table, 'where': where}

import heapq


def topo_sort(nodes: list, edges: list[tuple]) -> list:
    indegree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for a, b in edges:
        adj[a].append(b)
        indegree[b] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for neighbor in adj[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

