def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0

    if begin == end:
        return 2

    queue = deque([(begin, 1)])
    visited = {begin}

    while queue:
        word, level = queue.popleft()
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c == word[i]:
                    continue
                next_word = word[:i] + c + word[i + 1:]
                if next_word == end:
                    return level + 1
                if next_word in word_set and next_word not in visited:
                    visited.add(next_word)
                    queue.append((next_word, level + 1))

    return 0

from collections import deque

def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0
    if begin == end:
        return 2

    # Precompute pattern -> list of words mapping
    from collections import defaultdict
    pattern_map = defaultdict(list)
    for word in word_set:
        for i in range(len(word)):
            pattern = word[:i] + '*' + word[i+1:]
            pattern_map[pattern].append(word)

    queue = deque([(begin, 1)])
    visited = {begin}

    while queue:
        word, level = queue.popleft()
        for i in range(len(word)):
            pattern = word[:i] + '*' + word[i+1:]
            for neighbor in pattern_map[pattern]:
                if neighbor == end:
                    return level + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, level + 1))

    return 0

def evaluate(expr: str) -> float:
    tokens = _tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_unary()
            value = value * rhs if op == '*' else value / rhs
        return value

    def parse_unary():
        if peek() == '-':
            advance()
            return -parse_unary()
        if peek() == '+':
            advance()
            return parse_unary()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError('Unexpected end of expression')
        if tok == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError('Missing closing parenthesis')
            advance()
            return value
        if tok in ('+', '-', '*', '/', ')'):
            raise ValueError('Unexpected token %r' % tok)
        advance()
        try:
            return float(tok)
        except ValueError:
            raise ValueError('Invalid number %r' % tok)

    if not tokens:
        raise ValueError('Empty expression')

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError('Trailing tokens after expression')
    return result


def _tokenize(expr: str) -> list:
    if expr is None or not isinstance(expr, str):
        raise ValueError('Expression must be a string')

    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if ch in '+-*/()':
            tokens.append(ch)
            i += 1
            continue

        if ch in '0123456789.':
            start = i
            seen_dot = False
            while i < n and (expr[i].isdigit() or (expr[i] == '.' and not seen_dot)):
                if expr[i] == '.':
                    seen_dot = True
                i += 1
            num_str = expr[start:i]
            if num_str in ('.', ''):
                raise ValueError('Invalid number %r' % num_str)
            tokens.append(num_str)
            continue

        raise ValueError('Unexpected character %r' % ch)

    return tokens

