        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    def parse_factor():
        nonlocal pos
        tok = peek()
        if tok == '(':
            advance()
            value = parse_expression()
            if peek() != ')':
                raise ValueError("expected ')'")
            advance()
            return value
        if tok == '-':
            advance()
            return -parse_factor()
        if tok == '+':
            advance()
            return parse_factor()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if tok in ('+', '-', '*', '/', ')'):
            raise ValueError("unexpected token '%s'" % tok)
        advance()
        return tok

    if not tokens:
        raise ValueError("empty expression")

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("unexpected trailing tokens")
    return result


def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in '+-*/()':
            tokens.append(ch)
            i += 1
            continue
        if ch.isdigit() or ch == '.':
            start = i
            seen_dot = False
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                if expr[i] == '.':
                    if seen_dot:
                        raise ValueError("invalid number: multiple decimal points")
                    seen_dot = True
                i += 1
            number_str = expr[start:i]
            if number_str.count('.') > 1:
                raise ValueError("invalid number: '%s'" % number_str)
            if number_str in ('.', '+.', '-.'):
                raise ValueError("invalid number: '%s'" % number_str)
            tokens.append(float(number_str))
            continue
        raise ValueError("invalid character '%s'" % ch)
    return tokens

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    n, m = len(a), len(b)
    # Build LCS length table
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i + 1][j + 1] + 1
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    result = []
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            result.append((' ', a[i]))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            # deletion before insertion
            result.append(('-', a[i]))
            i += 1
        else:
            result.append(('+', b[j]))
            j += 1
    while i < n:
        result.append(('-', a[i]))
        i += 1
    while j < m:
        result.append(('+', b[j]))
        j += 1
    return result

