                    result.append(c)
                    i += 1
                    continue
            elif c == '"':
                result.append(c)
                i += 1
                while i < n:
                    ch = s[i]
                    if ch == '\\':
                        result.append(ch)
                        if i + 1 < n:
                            result.append(s[i + 1])
                            i += 2
                            continue
                        else:
                            raise ValueError("Bad escape")
                    elif ch == '"':
                        result.append(ch)
                        i += 1
                        break
                    else:
                        result.append(ch)
                        i += 1
