        elif c == '"':
            return parse_string(s, i, True)
        elif c == "'":
            return parse_string(s, i, False)
        elif c.isalpha() or c == '_':
            return parse_identifier(s, i)
        elif c == '-' or c.isdigit():
            return parse_number(s, i)
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    def parse_object(s, i):
        assert s[i] == '{'
        i += 1
        result = {}
        i = skip_ws(s, i)
        if i < len(s) and s[i] == '}':
            return {}, i + 1
        while True:
            i = skip_ws(s, i)
            if i >= len(s):
                raise ValueError("Unterminated object")
            if s[i] == '"' or s[i] == "'":
                key, i = parse_string(s, i, s[i] == "'")
            elif s[i].isalpha() or s[i] == '_':
                key, i = parse_key(s, i)
            else:
                raise ValueError(f"Expected key, got {s[i]!r}")
            i = skip_ws(s, i)
            if i >= len(s) or s[i] != ':':
                raise ValueError("Expected ':'")
            i += 1
            value, i = parse_value(s, i)
            result[key] = value
            i = skip_ws(s, i)
            if i >= len(s):
                raise ValueError("Unterminated object")
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == '}':
                return result, i + 1
            else:
                raise ValueError(f"Expected ',' or '}', got {s[i]!r}")

    def parse_array(s, i):
        assert s[i] == '['
        i += 1
        result = []
        i = skip_ws(s, i)
        if i < len(s) and s[i] == ']':
            return [], i + 1
        while True:
            value, i = parse_value(s, i)
            result.append(value)
            i = skip_ws(s, i)
            if i >= len(s):
                raise ValueError("Unterminated array")
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == ']':
                return result, i + 1
            else:
                raise ValueError(f"Expected ',' or ']', got {s[i]!r}")

    def parse_string(s, i, is_single):
        assert s[i] == ("'" if is_single else '"')
        quote = s[i]
        i += 1
        result = []
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == '\\':
                if i + 1 >= n:
                    raise ValueError("Bad escape")
                esc = s[i + 1]
                mapping = {'n': '\n', 't': '\t', '\\': '\\', '"': '"', "'": "'", '/': '/'}
                if esc not in mapping:
                    raise ValueError(f"Invalid escape: \\{esc}")
                result.append(mapping[esc])
                i += 2
            elif ch == quote:
                return ''.join(result), i + 1
            else:
                result.append(ch)
                i += 1
