            raise ValueError("Invalid key")
        return s[i:i + m], i + m

    def parse_identifier(s, i):
        m = 0
        n = len(s)
        while i + m < n and (s[i + m].isalnum() or s[i + m] == '_'):
            m += 1
        word = s[i:i + m]
        if word == 'true':
            return True, i + m
        elif word == 'false':
            return False, i + m
        elif word == 'null':
            return None, i + m
        else:
            raise ValueError(f"Invalid token: {word}")

    def parse_number(s, i):
        n = len(s)
        start = i
        if i < n and s[i] == '-':
            i += 1
        if i >= n or not s[i].isdigit():
            raise ValueError("Invalid number")
        while i < n and s[i].isdigit():
            i += 1
        is_float = False
        if i < n and s[i] == '.':
            is_float = True
            i += 1
            if i >= n or not s[i].isdigit():
                raise ValueError("Invalid number")
            while i < n and s[i].isdigit():
                i += 1
        if i < n and s[i] in 'eE':
            is_float = True
            i += 1
            if i < n and s[i] in '+-':
                i += 1
            if i >= n or not s[i].isdigit():
                raise ValueError("Invalid number")
            while i < n and s[i].isdigit():
                i += 1
        num_str = s[start:i]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    cleaned = strip_comments(text)
    value, pos = parse_value(cleaned, 0)
    pos = skip_ws(cleaned, pos)
    if pos != len(cleaned):
        raise ValueError("Trailing data after top-level value")
    return value

def parse_relaxed(text: str):
    ESCAPES = {
        'n': '\n', 't': '\t', 'r': '\r', '\\': '\\',
        '"': '"', "'": "'", '/': '/', 'b': '\b', 'f': '\f',
    }

    def parse_string(s, i):
        # s[i] is the opening quote
        quote = s[i]
        i += 1
        out = []
        while i < len(s):
            c = s[i]
            if c == quote:
                return ''.join(out), i + 1
            if c == '\\':
                i += 1
                if i >= len(s):
                    raise ValueError("Unterminated string escape")
                e = s[i]
                if e in ESCAPES:
                    out.append(ESCAPES[e])
                    i += 1
                elif e == 'u':
                    if i + 4 >= len(s):
                        raise ValueError("Invalid unicode escape")
                    code = int(s[i + 1:i + 5], 16)
                    out.append(chr(code))
                    i += 5
                else:
                    raise ValueError("Invalid escape: " + e)
            else:
                out.append(c)
                i += 1
        raise ValueError("Unterminated string")

    def skip_ws(s, i):
        while i < len(s):
            c = s[i]
            if c in ' \t\n\r':
                i += 1
            elif c == '/' and i + 1 < len(s) and s[i + 1] == '/':
                while i < len(s) and s[i] != '\n':
                    i += 1
            elif c == '/' and i + 1 < len(s) and s[i + 1] == '*':
                i += 2
                while i + 1 < len(s) and not (s[i] == '*' and s[i + 1] == '/'):
                    i += 1
                if i + 1 >= len(s):
                    raise ValueError("Unterminated block comment")
                i += 2
            else:
                break
        return i

    def parse_value(s, i):
        i = skip_ws(s, i)
        if i >= len(s):
            raise ValueError("Unexpected end of input")
        c = s[i]
        if c == '{':
            return parse_object(s, i)
        elif c == '[':
            return parse_array(s, i)
        elif c == '"' or c == "'":
            return parse_string(s, i)
        elif c == 't':
            if s[i:i + 4] == 'true':
                return True, i + 4
            raise ValueError("Invalid literal")
        elif c == 'f':
            if s[i:i + 5] == 'false':
                return False, i + 5
            raise ValueError("Invalid literal")
        elif c == 'n':
            if s[i:i + 4] == 'null':
                return None, i + 4
            raise ValueError("Invalid literal")
        elif c == '-' or c.isdigit():
            return parse_number(s, i)
        else:
            raise ValueError("Unexpected character: " + c)

    def parse_object(s, i):
        i += 1  # skip {
        result = {}
        i = skip_ws(s, i)
        if i < len(s) and s[i] == '}':
            return result, i + 1
        while True:
            i = skip_ws(s, i)
            if i >= len(s):
                raise ValueError("Unterminated object")
            if s[i] == '"':
                key, i = parse_string(s, i)
            elif s[i] in "A-Za-z_" or True and _is_ident_start(s[i]):
                key, i = parse_ident(s, i)
            else:
                raise ValueError("Invalid key")
            i = skip_ws(s, i)
            if i >= len(s) or s[i] != ':':
                raise ValueError("Expected ':'")
            i = skip_ws(s, i + 1)
            value, i = parse_value(s, i)
            result[key] = value
            i = skip_ws(s, i)
            if i >= len(s):
                raise ValueError("Unterminated object")
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == '}':
                return result, i + 1
            else:
                raise ValueError("Expected ',' or '}'")

    def parse_array(s, i):
        i += 1  # skip [
        result = []
        i = skip_ws(s, i)
        if i < len(s) and s[i] == ']':
            return result, i + 1
        while True:
            value, i = parse_value(s, i)
            result.append(value)
            i = skip_ws(s, i)
            if i >= len(s):
                raise ValueError("Unterminated array")
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == ']':
                return result, i + 1
            else:
                raise ValueError("Expected ',' or ']'")

    def parse_number(s, i):
        start = i
        if i < len(s) and s[i] == '-':
            i += 1
        while i < len(s) and s[i].isdigit():
            i += 1
        is_float = False
        if i < len(s) and s[i] == '.':
            is_float = True
            i += 1
            while i < len(s) and s[i].isdigit():
                i += 1
        if i < len(s) and s[i] in 'eE':
            is_float = True
            i += 1
            if i < len(s) and s[i] in '+-':
                i += 1
            while i < len(s) and s[i].isdigit():
                i += 1
        num_str = s[start:i]
        if num_str == '' or num_str == '-':
            raise ValueError("Invalid number")
        return (float(num_str) if is_float else int(num_str)), i

    def _is_ident_start(c):
        return c.isalpha() or c == '_'

    def parse_ident(s, i):
        start = i
        while i < len(s) and (s[i].isalnum() or s[i] == '_'):
            i += 1
        return s[start:i], i

    i = skip_ws(text, 0)
    value, i = parse_value(text, i)
    i = skip_ws(text, i)
    if i != len(text):
        raise ValueError("Trailing data after top-level value")
    return value

def topo_batches(deps: dict[str, list[str]]) -> list[list[str]]:
    # Collect all nodes (both keys and any node mentioned in dependency lists)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    # Build in-degree map and adjacency list (prereq -> node)
    in_degree = {node: 0 for node in all_nodes}
    dependents = {node: [] for node in all_nodes}
    for node, prereqs in deps.items():
        for prereq in prereqs:
            dependents[prereq].append(node)
            in_degree[node] += 1

    # Kahn's algorithm, level by level to form batches
    batches = []
    remaining = dict(in_degree)
    total = len(remaining)
    processed = 0

    while processed < total:
        current = sorted(node for node, deg in remaining.items() if deg == 0)
        if not current:
            raise ValueError("Graph contains a cycle")
        batches.append(current)
        for node in current:
            remaining.pop(node, None)
            processed += 1
            for dependent in dependents[node]:
                if dependent in remaining:
                    remaining[dependent] -= 1

    return batches

def topo_batches(deps: dict[str, list[str]]) -> list[list[str]]:
    # Collect all nodes (both keys and nodes referenced in dependency lists)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    # Build in-degree map and adjacency list (prereq -> node)
    in_degree = {node: 0 for node in all_nodes}
    dependents = {node: [] for node in all_nodes}

    for node, prereqs in deps.items():
        # Count unique prerequisites
        unique_prereqs = set(prereqs)
        in_degree[node] = len(unique_prereqs)
        for prereq in unique_prereqs:
            dependents[prereq].append(node)

    # Initialize the first batch with nodes that have no prerequisites
    current_level = [node for node in all_nodes if in_degree[node] == 0]
    batches = []

    while current_level:
        # Sort the current batch alphabetically
        current_level.sort()
        batches.append(current_level)

        # Compute the next batch
        next_level = []
        for node in current_level:
            for dependent in dependents[node]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    next_level.append(dependent)

        current_level = next_level

    # Check for cycles
    if len(batches) * 0 + sum(len(batch) for batch in batches) != len(all_nodes):
        raise ValueError("Graph contains a cycle")

    return batches

