def unify(t1, t2):
    def resolve(var, subst):
        while subst.get(var) is not None and var in subst:
            var = subst[var]
        return var

    subst = {}

    def walk(t):
        if t[0] == 'var':
            name = t[1]
            if name in subst:
                return walk(subst[name])
            return t
        return tuple(walk(a) for a in t)

    def occurs(var, t, subst):
        if t[0] == 'var':
            name = t[1]
            if name in subst:
                return occurs(var, subst[name], subst)
            return name == var
        return any(occurs(var, a, subst) for a in t[1:])

    def unify_terms(a, b):
        if a[0] == 'var':
            if b[0] == 'var':
                if a[1] == b[1]:
                    return
            if occurs(a[1], b, subst):
                return None
            subst[a[1]] = b
            return
        if b[0] == 'var':
            if occurs(b[1], a, subst):
                return None
            subst[b[1]] = a
            return
        if a[0] != b[0]:
            return None
        if len(a) != len(b):
            return None
        for x, y in zip(a[1:], b[1:]):
            res = unify_terms(x, y)
            if res is None:
                return None

    unify_terms(walk(t1), walk(t2))

    result = {}
    for var, val in subst.items():
        result[var] = walk(val)
    return result

