class RangeModule:
    def __init__(self):
        # List of non-overlapping, merged intervals stored as [left, right).
        self._intervals = []

    def _add_range(self, left, right):
        start = left
        end = right
        i = bisect.bisect_left(self._intervals, (start,))
        # Expand left to cover any overlapping/adjacent intervals.
        while i > 0 and self._intervals[i - 1][1] >= start:
            i -= 1
            start = min(start, self._intervals[i][0])
        # Expand right to cover any overlapping/adjacent intervals.
        while i < len(self._intervals) and self._intervals[i][0] <= end:
            end = max(end, self._intervals[i][1])
            i += 1
        self._intervals[i:] = [[start, end]]

    def add_range(self, left, right):
        if left < right:
            self._add_range(left, right)

    def query_range(self, left, right):
        i = bisect.bisect_right(self._intervals, (left, float('inf'))) - 1
        return i >= 0 and self._intervals[i][0] <= left and right <= self._intervals[i][1]

    def remove_range(self, left, right):
        i = bisect.bisect_left(self._intervals, (left,))
        while i < len(self._intervals) and self._intervals[i][0] < right:
            lo, hi = self._intervals[i]
            if lo < left and hi > right:
                self._intervals[i] = [lo, left]
                self._intervals.insert(i + 1, [right, hi])
                i += 2
            elif lo < left:
                self._intervals[i] = [lo, left]
                i += 1
            elif hi > right:
                self._intervals[i] = [right, hi]
                i += 1
            else:
                self._intervals.pop(i)

    def add(self, left, right):
        self.add_range(left, right)

    def query(self, left, right):
        return self.query_range(left, right)

    def remove(self, left, right):
        self.remove_range(left, right)

