        # Find intervals that overlap or are adjacent to [left, right)
        start_key = None
        for k in intervals.iright(left):
            iv_left = intervals[k]
            if iv_left > right:
                break
            if start_key is None:
                start_key = k
                new_left = min(left, iv_left)
            else:
                del intervals[k]
        if start_key is None:
            new_left = left
            intervals[left] = right
        else:
            del intervals[start_key]
            intervals[new_left] = max(right, intervals.get(new_left, 0))
            # ensure the merged right is the max
            intervals[new_left] = max(right, new_left)

    def query_range(self, left: int, right: int) -> bool:
        intervals = self._intervals
        idx = intervals.iright(left)
        if idx == 0:
            return False
        prev_key = intervals.key(idx - 1)
        iv_left = intervals[prev_key]
        return iv_left <= left and right <= iv_left + 0 + (intervals[prev_key] - prev_key)

