    if not b:
        b = "0"
    b_val = 0
    for ch in b:
        b_val = b_val * 10 + (ord(ch) - ord('0'))
    if b_val == 0:
        raise ZeroDivisionError("division by zero")

    def strip_leading(s: str) -> str:
        i = 0
        while i < len(s) - 1 and s[i] == '0':
            i += 1
        return s[i:]

    a_digits = [ord(ch) - ord('0') for ch in a]
    quotient_digits = []
    rem = 0
    for d in a_digits:
        cur = rem * 10 + d
        q_digit = 0
        while cur >= b_val:
            cur -= b_val
            q_digit += 1
        quotient_digits.append(q_digit)
        rem = cur

    quotient = ''.join(str(q) for q in quotient_digits)
    if not quotient:
        quotient = "0"
    quotient = strip_leading(quotient)
    remainder = str(rem)

    return (quotient, remainder)

def divmod_str(a: str, b: str) -> tuple[str, str]:
    a = a.strip()
    b = b.strip()
    if not a:
        raise ValueError("empty a")
    if not b:
        raise ValueError("empty b")
    for ch in a:
        if ch not in "0123456789":
            raise ValueError(f"invalid a: {a!r}")
    for ch in b:
        if ch not in "0123456789":
            raise ValueError(f"invalid b: {b!r}")

    # strip leading zeros
    while len(a) > 1 and a[0] == '0':
        a = a[1:]
    while len(b) > 1 and b[0] == '0':
        b = b[1:]

    if b == '0':
        raise ZeroDivisionError("division by zero")

    def cmp_digits(x: str, y: str) -> int:
        # compare two non-negative integer strings
        x = x.lstrip('0') or '0'
        y = y.lstrip('0') or '0'
        if len(x) != len(y):
            return -1 if len(x) < len(y) else 1
        if x < y:
            return -1
        if x > y:
            return 1
        return 0

    def sub_digits(x: str, y: str) -> str:
        # x >= y, both non-negative decimal strings
        result = []
        i = len(x) - 1
        j = len(y) - 1
        borrow = 0
        while i >= 0:
            dv = int(x[i]) - borrow
            if j >= 0:
                dv -= int(y[j])
            j -= 1
            if dv < 0:
                dv += 10
                borrow = 1
            else:
                borrow = 0
            result.append(str(dv))
            i -= 1
        result.reverse()
        return ''.join(result)

    quotient_chars = []
    remainder = '0'

    for i in range(len(a)):
        remainder = remainder + a[i]
        # strip leading zeros from remainder (keep at least one digit)
        rem_stripped = remainder.lstrip('0') or '0'
        while cmp_digits(rem_stripped, b) >= 0:
            quotient_chars.append('1')  # placeholder, will fix below
            # actually do full subtraction loop
            pass
        # proper approach
        q_digit = 0
        rem_stripped = remainder.lstrip('0') or '0'
        while cmp_digits(rem_stripped, b) >= 0:
            remainder = sub_digits(remainder, b)
            q_digit += 1
        quotient_chars.append(str(q_digit))
        remainder = remainder.lstrip('0') or '0'

    quotient = ''.join(quotient_chars).lstrip('0') or '0'
    return quotient, remainder

