class TxDict:
    def __init__(self, initial=None):
        self._data = dict(initial) if initial else {}
        self._stack = []

    def __getitem__(self, key):
        return self._data[key]

    def __setitem__(self, key, value):
        self._data[key] = value

    def __delitem__(self, key):
        del self._data[key]

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __iter__(self):
        return iter(self._data)

    def get(self, key, default=None):
        return self._data.get(key, default)

    @contextmanager
    def transaction(self):
        yield self.begin()

    def begin(self):
        if not self._stack:
            self._snapshot = dict(self._data)
        self._stack.append(set(self._data.keys()))
        return self

    def commit(self):
        if not self._stack:
            raise RuntimeError("no active transaction")
        self._stack.pop()

    def rollback(self):
        if not self._stack:
            raise RuntimeError("no active transaction")
        self._stack.pop()
        if not self._stack:
            self._data.clear()
            self._data.update(self._snapshot)
        else:
            for key in list(self._data.keys()):
                if key not in self._stack[-1]:
                    del self._data[key]

from contextlib import contextmanager


class TxDict:
    def __init__(self):
        self._data = {}
        self._stack = []

    def __getitem__(self, key):
        return self._data[key]

    def __setitem__(self, key, value):
        self._data[key] = value

    def __delitem__(self, key):
        del self._data[key]

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __iter__(self):
        return iter(self._data)

    def get(self, key, default=None):
        return self._data.get(key, default)

    @contextmanager
    def transaction(self):
        if not self._stack:
            try:
                yield self
                self._stack.pop()
            except BaseException:
                self._stack.pop()
                raise
        else:
            try:
                yield self
            except BaseException:
                raise

    def commit(self):
        if not self._stack:
            raise RuntimeError("No active transaction")
        if len(self._stack) == 1:
            self._stack.pop()
        else:
            self._stack.pop()
            self._stack[-1]._merge(self._stack[-1])

    def rollback(self):
        if not self._stack:
            raise RuntimeError("No active transaction")
        self._stack.pop()

