def run_query(sql: str, rows: list[dict]) -> list[dict]:
    tokens = _tokenize(sql)
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def expect_keyword(kw):
        t = peek()
        if t is None or t.upper() != kw.upper():
            raise ValueError(f"Expected keyword {kw}")
        return advance()

    # SELECT ...
    expect_keyword("SELECT")

    # Parse selected columns
    select_cols = []
    while True:
        # Could be *
        if peek() == "*":
            advance()
            select_cols.append(("*", None))
        else:
            col = advance()
            alias = None
            if peek() and peek().lower() == "as":
                advance()
                alias = advance()
            select_cols.append((col, alias))
        if peek() == ",":
            advance()
        else:
            break

    # FROM t
    expect_keyword("FROM")
    advance()  # table name, ignored

    # WHERE
    condition = None
    if peek() and peek().upper() == "WHERE":
        advance()
        condition = _parse_or(tokens, pos)

    # ORDER BY
    order_by = []
    if peek() and peek().upper() == "ORDER":
        advance()
        expect_keyword("BY")
        while True:
            col = advance()
            direction = "ASC"
            if peek() and peek().upper() in ("ASC", "DESC"):
                direction = advance().upper()
            order_by.append((col, direction))
            if peek() == ",":
                advance()
            else:
                break

    # LIMIT
    limit = None
    if peek() and peek().upper() == "LIMIT":
        advance()
        limit = int(advance())

    # Filter
    result = []
    for row in rows:
        if condition is None or _eval_condition(condition, row):
            result.append(row)

    # Order by
    if order_by:
        # Process right-to-left for stable multi-key sort
        for col, direction in reversed(order_by):
            reverse = (direction == "DESC")
            result.sort(key=lambda r, c=col: _sort_key(r.get(c)), reverse=reverse)

    # Project
    projected = []
    for row in result:
        d = {}
        for col, alias in select_cols:
            if col == "*":
                d.clear()
                d.update(row)
            else:
                key = alias if alias is not None else col
                d[key] = row.get(col)
        projected.append(d)

    if limit is not None:
        projected = projected[:limit]

    return projected


def _sort_key(value):
    if value is None:
        return (2, 0)
    if isinstance(value, bool):
        return (0, int(value))
    if isinstance(value, (int, float)):
        return (0, value)
    return (1, str(value))


def _parse_or(tokens, pos):
    left = _parse_and(tokens, pos)
    while peek_is_keyword(tokens, pos, "OR"):
        pos[0] += 1
        right = _parse_and(tokens, pos)
        left = ("OR", left, right)
    return left


def _parse_and(tokens, pos):
    left = _parse_comparison(tokens, pos)
    while peek_is_keyword(tokens, pos, "AND"):
        pos[0] += 1
        right = _parse_comparison(tokens, pos)
        left = ("AND", left, right)
    return left


def _parse_comparison(tokens, pos):
    t = peek(tokens, pos)
    if t == "(":
        pos[0] += 1
        expr = _parse_or(tokens, pos)
        if peek(tokens, pos) != ")":
            raise ValueError("Expected )")
        advance(tokens, pos)
        return expr
    # column
    col = advance(tokens, pos)
    op = advance(tokens, pos)
    if op not in ("=", "!=", "<", "<=", ">", ">="):
        raise ValueError(f"Invalid operator {op}")
    val = advance(tokens, pos)
    return ("CMP", col, op, _parse_literal(val))


def _parse_literal(val):
    if val.startswith("'") and val.endswith("'"):
        return ("str", val[1:-1])
    try:
        return ("int", int(val))
    except ValueError:
        try:
            return ("float", float(val))
        except ValueError:
            raise ValueError(f"Invalid literal {val}")


def peek_is_keyword(tokens, pos, kw):
    t = peek(tokens, pos)
    return t is not None and t.upper() == kw.upper()


def peek(tokens, pos):
    return tokens[pos[0]] if pos[0] < len(tokens) else None


def advance(tokens, pos):
    t = tokens[pos[0]]
    pos[0] += 1
    return t


def _tokenize(sql):
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        if c == "'":
            j = i + 1
            buf = []
            while j < n and sql[j] != "'":
                buf.append(sql[j])
                j += 1
            if j >= n:
                raise ValueError("Unterminated string literal")
            tokens.append("".join(buf))
            i = j + 1
            continue
        if c in "=!<>":
            j = i
            if j + 1 < n and sql[j + 1] == "=":
                j += 1
            tokens.append(sql[i:j + 1])
            i = j + 1
            continue
        if c == "(":
            tokens.append("(")
            i += 1
            continue
        if c == ")":
            tokens.append(")")
            i += 1
            continue
        if c == ",":
            tokens.append(",")
            i += 1
            continue
        if c == "*":
            tokens.append("*")
            i += 1
            continue
        # identifier / number / keyword
        j = i
        while j < n and not sql[j].isspace() and sql[j] not in "=!<>(),*'":
            j += 1
        tokens.append(sql[i:j])
        i = j
    return tokens

