def run_query(sql: str, rows: list[dict]) -> list[dict]:
    sql = sql.strip()
    if not sql:
        raise ValueError("Empty query")

    tokens = _tokenize(sql)
    if not tokens:
        raise ValueError("Empty query")

    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def expect_keyword(kw):
        tok = peek()
        if tok is None or tok[0] != kw.upper():
            raise ValueError(f"Expected {kw}")
        pos[0] += 1
        return tok

    def match_keyword(kw):
        tok = peek()
        if tok is not None and tok[0] == kw.upper():
            pos[0] += 1
            return True
        return False

    # SELECT
    expect_keyword("SELECT")

    # Column list
    selected = []  # list of (name, alias)
    if peek() == "*":
        advance()
        selected.append(("*", "*"))
    else:
        while True:
            name_tok = peek()
            if name_tok is None or name_tok[0] != "IDENT":
                raise ValueError("Expected column name")
            advance()
            name = name_tok[1]
            alias = name
            if match_keyword("AS"):
                alias_tok = peek()
                if alias_tok is None or alias_tok[0] != "IDENT":
                    raise ValueError("Expected alias")
                advance()
                alias = alias_tok[1]
            selected.append((name, alias))
            if peek() == ",":
                advance()
            else:
                break

    # FROM
    expect_keyword("FROM")
    # table name ignored; consume it if present
    if peek() is not None and peek()[0] in ("IDENT", "STRING"):
        advance()

    # WHERE
    condition = None
    if match_keyword("WHERE"):
        condition = _parse_expr(tokens, pos)

    # ORDER BY
    order = []
    if match_keyword("ORDER"):
        expect_keyword("BY")
        while True:
            col_tok = peek()
            if col_tok is None or col_tok[0] != "IDENT":
                raise ValueError("Expected ORDER BY column")
            advance()
            col = col_tok[1]
            direction = "ASC"
            if peek() is not None and peek()[0] == "DIR":
                direction = peek()[1]
                advance()
            elif peek() is not None and peek()[0] in ("ASC", "DESC"):
                direction = peek()[1]
                advance()
            order.append((col, direction))
            if peek() == ",":
                advance()
            else:
                break

    # LIMIT
    limit = None
    if match_keyword("LIMIT"):
        tok = peek()
        if tok is None or tok[0] != "NUMBER":
            raise ValueError("Expected LIMIT value")
        advance()
        limit = int(tok[1])

    # Evaluate
    result = []
    for row in rows:
        if condition is not None and not _eval_condition(condition, row):
            continue
        out = {}
        for name, alias in selected:
            if name == "*":
                out.update(row)
            else:
                out[alias] = row.get(name)
        result.append(out)

    # ORDER BY
    if order:
        def sort_key(record):
            keys = []
            for col, direction in order:
                val = record.get(col)
                keys.append((val, direction))
            return keys
        # Multi-key sort with mixed directions
        for col, direction in reversed(order):
            reverse = (direction == "DESC")

            def keyfunc(record, c=col):
                return record.get(c)

            result.sort(key=keyfunc, reverse=reverse)

    if limit is not None:
        result = result[:limit]

    return result


def _tokenize(sql):
    tokens = []
    i = 0
    n = len(sql)
    keywords = {"SELECT", "FROM", "WHERE", "ORDER", "BY", "ASC", "DESC", "LIMIT",
                "AND", "OR", "NOT", "NULL", "AS"}
    operators = {"=", "!=", "<", "<=", ">", ">="}

    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        if c == "'":
            j = i + 1
            buf = []
            while j < n:
                if sql[j] == "'" and j + 1 < n and sql[j + 1] == "'":
                    buf.append("'")
                    j += 2
                    continue
                if sql[j] == "'":
                    break
                buf.append(sql[j])
                j += 1
            if j >= n:
                raise ValueError("Unterminated string literal")
            i = j + 1
            tokens.append(("STRING", "".join(buf)))
            continue
        if c.isdigit():
            j = i
            while j < n and (sql[j].isdigit() or sql[j] == "."):
                j += 1
            numstr = sql[i:j]
            if "." in numstr:
                tokens.append(("NUMBER", float(numstr)))
            else:
                tokens.append(("NUMBER", int(numstr)))
            i = j
            continue
        if c.isalpha() or c == "_":
            j = i
            while j < n and (sql[j].isalnum() or sql[j] == "_"):
                j += 1
            word = sql[i:j]
            up = word.upper()
            if up in keywords:
                if up in ("ASC", "DESC"):
                    tokens.append(("DIR", up))
                else:
                    tokens.append(("KEYWORD", up))
            else:
                tokens.append(("IDENT", word))
            i = j
            continue
        if c == "*" or c == "," or c == "(" or c == ")":
            tokens.append((c, c))
            i += 1
            continue
        if c == "!":
            if i + 1 < n and sql[i + 1] == "=":
                tokens.append(("OP", "!="))
                i += 2
                continue
            raise ValueError(f"Unexpected character: {c}")
        if c == "<":
            if i + 1 < n and sql[i + 1] == "=":
                tokens.append(("OP", "<="))
                i += 2
                continue
            tokens.append(("OP", "<"))
            i += 1
            continue
        if c == ">":
            if i + 1 < n and sql[i + 1] == "=":
                tokens.append(("OP", ">="))
                i += 2
                continue
            tokens.append(("OP", ">"))
            i += 1
            continue
        if c == "=":
            tokens.append(("OP", "="))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    # Convert KEYWORD tokens to their keyword name as token type
    result = []
    for typ, val in tokens:
        if typ == "KEYWORD":
            result.append((val, val))
        else:
            result.append((typ, val))
    return result


def _parse_expr(tokens, pos):
    return _parse_or(tokens, pos)


def _parse_or(tokens, pos):
    left = _parse_and(tokens, pos)
    while True:
        tok = tokens[pos[0]] if pos[0] < len(tokens) else None
        if tok is not None and tok[0] == "OR":
            pos[0] += 1
            right = _parse_and(tokens, pos)
            left = ("OR", left, right)
        else:
            break
    return left


def _parse_and(tokens, pos):
    left = _parse_unary(tokens, pos)
    while True:
        tok = tokens[pos[0]] if pos[0] < len(tokens) else None
        if tok is not None and tok[0] == "AND":
            pos[0] += 1
            right = _parse_unary(tokens, pos)
            left = ("AND", left, right)
        else:
            break
    return left


def _parse_unary(tokens, pos):
    tok = tokens[pos[0]] if pos[0] < len(tokens) else None
    if tok is not None and tok[0] == "NOT":
        pos[0] += 1
        operand = _parse_unary(tokens, pos)
        return ("NOT", operand)
    return _parse_primary(tokens, pos)


def _parse_primary(tokens, pos):
    tok = tokens[pos[0]] if pos[0] < len(tokens) else None
    if tok is not None and tok[0] == "(":
        pos[0] += 1
        expr = _parse_or(tokens, pos)
        close = tokens[pos[0]] if pos[0] < len(tokens) else None
        if close is None or close[0] != ")":
            raise ValueError("Expected closing parenthesis")
        pos[0] += 1
        return expr
    return _parse_condition(tokens, pos)


def _parse_condition(tokens, pos):
    col_tok = tokens[pos[0]] if pos[0] < len(tokens) else None
    if col_tok is None or col_tok[0] != "IDENT":
        raise ValueError("Expected column name in condition")
    pos[0] += 1
    col = col_tok[1]

    op_tok = tokens[pos[0]] if pos[0] < len(tokens) else None
    if op_tok is None or op_tok[0] != "OP":
        raise ValueError("Expected comparison operator")
    pos[0] += 1
    op = op_tok[1]

    val_tok = tokens[pos[0]] if pos[0] < len(tokens) else None
    if val_tok is None or val_tok[0] not in ("NUMBER", "STRING"):
        raise ValueError("Expected literal value in condition")
    pos[0] += 1
    val = val_tok[1]

    return ("COND", col, op, val)


def _eval_condition(expr, row):
    kind = expr[0]
    if kind == "AND":
        return _eval_condition(expr[1], row) and _eval_condition(expr[2], row)
    if kind == "OR":
        return _eval_condition(expr[1], row) or _eval_condition(expr[2], row)
    if kind == "NOT":
        return not _eval_condition(expr[1], row)
    if kind == "COND":
        _, col, op, val = expr
        actual = row.get(col)
        return _compare(actual, op, val)
    raise ValueError("Invalid condition")


def _compare(actual, op, val):
    if actual is None:
        return False
    # Ensure comparable types
    if isinstance(val, (int, float)) and isinstance(actual, str):
        try:
            actual = float(actual)
        except (ValueError, TypeError):
            return False
    if isinstance(val, str) and isinstance(actual, (int, float)):
        try:
            val = float(val)
        except (ValueError, TypeError):
            return False
    try:
        if op == "=":
            return actual == val
        if op == "!=":
            return actual != val
        if op == "<":
            return actual < val
        if op == "<=":
            return actual <= val
        if op == ">":
            return actual > val
        if op == ">=":
            return actual >= val
    except TypeError:
        return False
    return False

