from sortedcontainers import SortedList


class MedianStream:
    def __init__(self):
        self._counts = {}
        self._sl = SortedList()
        self._n = 0

    def add(self, x: float) -> None:
        self._counts[x] = self._counts.get(x, 0) + 1
        self._sl.add(x)
        self._n += 1

    def remove(self, x: float) -> None:
        if self._counts.get(x, 0) == 0:
            raise ValueError("value not present")
        self._counts[x] -= 1
        self._sl.remove(x)
        self._n -= 1

    def median(self) -> float:
        if self._n == 0:
            raise ValueError("no values")
        if self._n % 2 == 1:
            return self._sl[self._n // 2]
        lo = self._sl[self._n // 2 - 1]
        hi = self._sl[self._n // 2]
        return (lo + hi) / 2.0

import heapq


class MedianStream:
    def __init__(self):
        self._low = []      # max-heap (negated) of smaller half
        self._high = []     # min-heap of larger half (with lazy deletion)
        self._stale = {}    # count of pending deletions in _high
        self._size = 0

    def add(self, x: float) -> None:
        if not self._low or x <= -self._low[0]:
            heapq.heappush(self._low, -x)
        else:
            heapq.heappush(self._high, x)
            self._stale[x] = self._stale.get(x, 0) + 1
        self._size += 1
        self._rebalance()

    def _rebalance(self):
        # Maintain: active_low == active_high or active_low == active_high + 1
        while True:
            self._prune_high()
            low, high = len(self._low), len(self._high)
            if low > high + 1:
                val = heapq.heappop(self._low)
                heapq.heappush(self._high, -val)
                self._stale[-val] = self._stale.get(-val, 0) + 1
            elif high > low:
                val = heapq.heappop(self._high)
                heapq.heappush(self._low, -val)
            else:
                break

    def _prune_high(self):
        while self._high and self._high[0] in self._stale:
            top = heapq.heappop(self._high)
            self._stale[top] -= 1
            if self._stale[top] == 0:
                del self._stale[top]

    def remove(self, x: float) -> None:
        if not self._low and not self._high:
            raise ValueError("value not present")
        # Determine which heap contains x.
        if self._low and x <= -self._low[0]:
            # x lives in the low heap; we must remove it from there.
            # Mark the low heap's top region: since we can't delete arbitrary
            # elements from a heap, move low's elements via rebuild only if needed.
            # Instead, ensure x is the max of low by pushing a sentinel? 
            # Correct approach: remove from low by marking stale is impossible,
            # so we pop low's max and reinsert, but x may not be the max.
            # Use lazy approach on low too.
            self._remove_from_low(x)
        else:
            self._stale[x] = self._stale.get(x, 0) + 1
            self._size -= 1
            self._rebalance()
        return

    def _remove_from_low(self, x):
        # x is in low. Verify presence.
        # Count occurrences of x in low.
        found = self._count_low(x)
        if found == 0:
            raise ValueError("value not present")
        self._size -= 1
        # We need to actually remove one occurrence from low.
        # Rebuild low without one occurrence of x.
        new_low = [v for v in self._low if v != -x]
        if len(new_low) == len(self._low):
            raise ValueError("value not present")
        heapq.heapify(new_low)
        self._low = new_low
        self._rebalance()

    def _count_low(self, x):
        return sum(1 for v in self._low if -v == x)

    def median(self) -> float:
        if self._size == 0:
            raise ValueError("no elements")
        self._prune_high()
        low, high = len(self._low), len(self._high)
        if low > high:
            return float(-self._low[0])
        return (-self._low[0] + self._high[0]) / 2.0
